cat > <WORKSPACE>/anthropic/opus-5/max/index.html <<'RMN_EOF'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="dark">
<meta name="theme-color" content="#05060a">
<title>Vegan Ramen</title>
<style>
  html, body { margin: 0; padding: 0; height: 100%; background: #05060a; }
  body {
    overflow: hidden;
    overscroll-behavior: none;
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
    -webkit-tap-highlight-color: transparent;
  }
  #scene { position: fixed; inset: 0; display: block; width: 100%; height: 100%; }
</style>
</head>
<body>
<canvas id="scene"></canvas>
<script>
(function () {
'use strict';

/* ============================================================
   1. math + noise
   ============================================================ */

var TAU = Math.PI * 2;
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function lerp(a, b, t) { return a + (b - a) * t; }
function smooth(e0, e1, x) { var t = clamp((x - e0) / (e1 - e0), 0, 1); return t * t * (3 - 2 * t); }

function rngFrom(seed) {
  var a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

var PERM = new Uint8Array(512);
(function () {
  var r = rngFrom(20260904);
  var p = new Uint8Array(256), i, j, t;
  for (i = 0; i < 256; i++) p[i] = i;
  for (i = 255; i > 0; i--) { j = (r() * (i + 1)) | 0; t = p[i]; p[i] = p[j]; p[j] = t; }
  for (i = 0; i < 512; i++) PERM[i] = p[i & 255];
})();

var GX = [1, -1, 1, -1, 1, -1, 0, 0];
var GY = [1, 1, -1, -1, 0, 0, 1, -1];
function fade(t) { return t * t * t * (t * (t * 6 - 15) + 10); }

/* gradient noise, roughly [-1, 1] */
function noise2(x, y) {
  var xi = Math.floor(x), yi = Math.floor(y);
  var X = xi & 255, Y = yi & 255;
  var xf = x - xi, yf = y - yi;
  var u = fade(xf), v = fade(yf);
  var A = PERM[X] + Y, B = PERM[X + 1] + Y;
  var g00 = PERM[A] & 7, g01 = PERM[A + 1] & 7, g10 = PERM[B] & 7, g11 = PERM[B + 1] & 7;
  var n00 = GX[g00] * xf + GY[g00] * yf;
  var n10 = GX[g10] * (xf - 1) + GY[g10] * yf;
  var n01 = GX[g01] * xf + GY[g01] * (yf - 1);
  var n11 = GX[g11] * (xf - 1) + GY[g11] * (yf - 1);
  return lerp(lerp(n00, n10, u), lerp(n01, n11, u), v);
}

function fbm(x, y, oct) {
  var v = 0, a = 0.5, f = 1;
  for (var i = 0; i < oct; i++) { v += a * noise2(x * f, y * f); f *= 2.03; a *= 0.5; }
  return v;
}

/* curl of a scalar noise potential -> divergence-free flow, what smoke wants */
function potential(x, y, t) {
  return noise2(x, y + t) + noise2(x * 2.17 + 19.3, y * 2.17 - t * 1.55 + 7.1) * 0.45;
}
var CURL = { x: 0, y: 0 };
function curl(x, y, t, out) {
  var e = 0.09, ie = 1 / (2 * e);
  out.x = (potential(x, y + e, t) - potential(x, y - e, t)) * ie;
  out.y = -(potential(x + e, y, t) - potential(x - e, y, t)) * ie;
}

/* ============================================================
   2. canvas + scene state
   ============================================================ */

var cv = document.getElementById('scene');
var ctx = cv.getContext('2d', { alpha: false });

var S = {
  w: 0, h: 0, dpr: 1,
  cx: 0, cy: 0, R: 300,
  bg: null
};

var G = null;              /* geometry */
var BB = null;             /* bowl bounding box */
var LA = null, LB = null;  /* baked layers: A = vessel + broth, B = food + rim */
var pBody = null, pRim = null, pWall = null, pRimClip = null, pBrothClip = null;

var T = 0;                 /* scene clock, seconds */
var reduced = false;
var rafId = 0;
var lastTs = 0;
var noriBox = null;
var frameAvg = 16.7, frameCount = 0, downgraded = false;

/* the pointer is a soft, laggy thing; it also drifts on its own when nobody is there */
var ptr = {
  x: 0, y: 0, tx: 0, ty: 0,
  vx: 0, vy: 0,
  lastMove: -1e9,
  everMoved: false
};

/* composition constants, in units of the broth radius (top-down disc space) */
var FLAT = 0.42;                                    /* rim ellipse ry / rx */
var MOUND = { u: -0.14, v: 0.18, r: 0.44, h: 0.30 };  /* the noodle pile */

/* ============================================================
   3. geometry
   ============================================================ */

/* map a top-down point on the broth disc to screen space */
function P(g, u, v) {
  return { x: g.bx + u * g.brothR, y: g.by + v * g.brothR * g.s };
}

/* how high the food sits above the broth at (u,v), in broth-radius units */
function surfaceHeight(u, v) {
  var dx = (u - MOUND.u) / MOUND.r, dy = (v - MOUND.v) / MOUND.r;
  var d2 = dx * dx + dy * dy;
  if (d2 >= 1) return 0;
  return MOUND.h * Math.sqrt(1 - d2) * 0.92;
}

function buildGeom() {
  var R = S.R, s = FLAT;
  var g = {
    R: R, s: s,
    cx: S.cx, cy: S.cy,
    Ro: R * 1.045,
    rimRy: R * s,
    outRy: R * 1.045 * s,
    brothR: R * 0.935,
    brothRy: R * 0.935 * s,
    brothDrop: R * 0.115,
    depth: R * 0.66,
    footR: R * 0.40
  };
  g.footRy = g.footR * s * 0.92;
  g.bx = g.cx;
  g.by = g.cy + g.brothDrop;
  return g;
}

/* outer profile half-width at t (0 = rim, 1 = foot) */
function halfWidth(g, t) {
  return g.footR + (g.Ro - g.footR) * (1 - Math.pow(clamp(t, 0, 1), 1.55));
}

function buildPaths(g) {
  var p = new Path2D();
  p.moveTo(g.cx + g.Ro, g.cy);
  p.ellipse(g.cx, g.cy, g.Ro, g.outRy, 0, 0, Math.PI, false);
  p.bezierCurveTo(
    g.cx - g.Ro * 1.005, g.cy + g.depth * 0.34,
    g.cx - g.R * 0.815, g.cy + g.depth * 0.80,
    g.cx - g.footR, g.cy + g.depth);
  p.ellipse(g.cx, g.cy + g.depth, g.footR, g.footRy, 0, Math.PI, 0, true);
  p.bezierCurveTo(
    g.cx + g.R * 0.815, g.cy + g.depth * 0.80,
    g.cx + g.Ro * 1.005, g.cy + g.depth * 0.34,
    g.cx + g.Ro, g.cy);
  p.closePath();
  pBody = p;

  var r = new Path2D();
  r.ellipse(g.cx, g.cy, g.Ro, g.outRy, 0, 0, TAU);
  r.moveTo(g.cx + g.R, g.cy);
  r.ellipse(g.cx, g.cy, g.R, g.rimRy, 0, 0, TAU);
  pRim = r;

  var w = new Path2D();
  w.ellipse(g.cx, g.cy, g.R, g.rimRy, 0, 0, TAU);
  w.moveTo(g.bx + g.brothR, g.by);
  w.ellipse(g.bx, g.by, g.brothR, g.brothRy, 0, 0, TAU);
  pWall = w;

  var rc = new Path2D();
  rc.ellipse(g.cx, g.cy, g.R, g.rimRy, 0, 0, TAU);
  pRimClip = rc;

  var bc = new Path2D();
  bc.ellipse(g.bx, g.by, g.brothR, g.brothRy, 0, 0, TAU);
  pBrothClip = bc;
}

function bowlBounds(g) {
  var pad = g.R * 0.12;
  var top = g.cy - g.outRy - g.R * 0.34;
  var contact = g.cy + g.depth + g.footRy;
  return {
    x: g.cx - g.Ro - pad,
    y: top,
    w: (g.Ro + pad) * 2,
    h: (contact + g.R * 0.46) - top,
    contact: contact
  };
}

function makeLayer(bb, dpr) {
  var c = document.createElement('canvas');
  c.width = Math.max(1, Math.ceil(bb.w * dpr));
  c.height = Math.max(1, Math.ceil(bb.h * dpr));
  var x = c.getContext('2d');
  x.setTransform(dpr, 0, 0, dpr, -bb.x * dpr, -bb.y * dpr);
  return { cv: c, ctx: x, w: c.width / dpr, h: c.height / dpr };
}
RMN_EOF
