/* ============================================================
   4. the vessel  (baked into layer A)
   ============================================================ */

function paintExterior(x, g, bb) {
  x.save();
  x.clip(pBody);

  var lg = x.createLinearGradient(0, g.cy - g.outRy, 0, g.cy + g.depth + g.footRy);
  lg.addColorStop(0.00, '#4a3524');
  lg.addColorStop(0.07, '#2b201a');
  lg.addColorStop(0.20, '#191821');
  lg.addColorStop(0.52, '#0f0f16');
  lg.addColorStop(1.00, '#07070c');
  x.fillStyle = lg;
  x.fillRect(bb.x, bb.y, bb.w, bb.h);

  /* cylindrical falloff: the silhouette edges roll away from the light */
  var hg = x.createLinearGradient(g.cx - g.Ro, 0, g.cx + g.Ro, 0);
  hg.addColorStop(0.00, 'rgba(0,0,0,0.62)');
  hg.addColorStop(0.24, 'rgba(0,0,0,0.10)');
  hg.addColorStop(0.46, 'rgba(255,232,200,0.05)');
  hg.addColorStop(0.72, 'rgba(0,0,0,0.06)');
  hg.addColorStop(1.00, 'rgba(0,0,0,0.50)');
  x.fillStyle = hg;
  x.fillRect(bb.x, bb.y, bb.w, bb.h);

  /* throwing lines from the wheel */
  x.lineWidth = Math.max(0.6, g.R * 0.0045);
  for (var k = 1; k <= 9; k++) {
    var t = k / 10;
    var rx = halfWidth(g, t);
    var y = g.cy + g.depth * t;
    var a = 0.030 * (1 - t * 0.5);
    x.beginPath();
    x.ellipse(g.cx, y, rx * 0.995, rx * g.s * 0.9, 0, 0.12, Math.PI - 0.12);
    x.strokeStyle = 'rgba(255,222,186,' + a.toFixed(3) + ')';
    x.stroke();
    x.beginPath();
    x.ellipse(g.cx, y + g.R * 0.012, rx * 0.995, rx * g.s * 0.9, 0, 0.14, Math.PI - 0.14);
    x.strokeStyle = 'rgba(0,0,0,0.20)';
    x.stroke();
  }

  /* glaze sheen: a soft broad reflection low on the left flank */
  x.globalCompositeOperation = 'lighter';
  var sx = g.cx - g.R * 0.46, sy = g.cy + g.depth * 0.44;
  var sg = x.createRadialGradient(sx, sy, 0, sx, sy, g.R * 0.62);
  sg.addColorStop(0.00, 'rgba(150,172,208,0.10)');
  sg.addColorStop(0.45, 'rgba(120,142,180,0.035)');
  sg.addColorStop(1.00, 'rgba(90,110,150,0)');
  x.fillStyle = sg;
  x.fillRect(bb.x, bb.y, bb.w, bb.h);

  /* warm spill from the mouth pooling on the upper flank */
  var wg = x.createRadialGradient(g.cx, g.cy, g.R * 0.10, g.cx, g.cy, g.R * 1.15);
  wg.addColorStop(0.00, 'rgba(214,128,52,0.28)');
  wg.addColorStop(0.40, 'rgba(190,104,42,0.10)');
  wg.addColorStop(1.00, 'rgba(160,80,30,0)');
  x.fillStyle = wg;
  x.fillRect(bb.x, bb.y, bb.w, bb.h);
  x.globalCompositeOperation = 'source-over';

  x.restore();

  /* rim lights hug the silhouette: cool from behind-left, warm from the right */
  x.save();
  x.lineJoin = 'round';
  var wide = x.createLinearGradient(g.cx - g.Ro, 0, g.cx + g.Ro, 0);
  wide.addColorStop(0.00, 'rgba(122,158,214,0.20)');
  wide.addColorStop(0.20, 'rgba(100,130,180,0.03)');
  wide.addColorStop(0.60, 'rgba(0,0,0,0)');
  wide.addColorStop(0.84, 'rgba(226,140,62,0.05)');
  wide.addColorStop(1.00, 'rgba(255,168,86,0.22)');
  x.lineWidth = Math.max(3, g.R * 0.045);
  x.strokeStyle = wide;
  x.globalCompositeOperation = 'lighter';
  x.stroke(pBody);

  var tight = x.createLinearGradient(g.cx - g.Ro, 0, g.cx + g.Ro, 0);
  tight.addColorStop(0.00, 'rgba(176,206,255,0.72)');
  tight.addColorStop(0.13, 'rgba(130,164,220,0.10)');
  tight.addColorStop(0.55, 'rgba(0,0,0,0)');
  tight.addColorStop(0.87, 'rgba(238,152,70,0.12)');
  tight.addColorStop(1.00, 'rgba(255,190,110,0.80)');
  x.lineWidth = Math.max(1.1, g.R * 0.010);
  x.strokeStyle = tight;
  x.stroke(pBody);
  x.globalCompositeOperation = 'source-over';
  x.restore();
}

function paintInnerWall(x, g, bb) {
  x.save();
  x.clip(pRimClip);

  var y0 = g.cy - g.rimRy;
  var y1 = g.by - g.brothRy;
  var lg = x.createLinearGradient(0, y0, 0, y1);
  lg.addColorStop(0.00, '#3a2617');
  lg.addColorStop(0.26, '#20120a');
  lg.addColorStop(0.62, '#3d1e0b');
  lg.addColorStop(1.00, '#93501c');
  x.fillStyle = lg;
  x.fill(pWall, 'evenodd');

  /* the broth is the light source, so the wall glows where it meets the liquid */
  x.globalCompositeOperation = 'lighter';
  x.save();
  x.clip(pWall, 'evenodd');
  x.translate(g.bx, g.by);
  x.scale(1, g.s);
  var bg = x.createRadialGradient(0, 0, g.brothR * 0.55, 0, 0, g.brothR * 1.55);
  bg.addColorStop(0.00, 'rgba(255,150,60,0)');
  bg.addColorStop(0.60, 'rgba(236,132,48,0.26)');
  bg.addColorStop(1.00, 'rgba(160,70,20,0)');
  x.fillStyle = bg;
  x.beginPath();
  x.arc(0, 0, g.brothR * 1.6, 0, TAU);
  x.fill();
  x.restore();
  x.globalCompositeOperation = 'source-over';

  /* faint vertical throwing texture inside the wall */
  x.save();
  x.clip(pWall, 'evenodd');
  x.lineWidth = Math.max(0.5, g.R * 0.004);
  for (var i = 0; i < 46; i++) {
    var a = (i / 46) * Math.PI + Math.PI;
    var xx = g.cx + Math.cos(a) * g.R;
    var yt = g.cy + Math.sin(a) * g.rimRy;
    var yb = g.by + Math.sin(a) * g.brothRy;
    x.beginPath();
    x.moveTo(xx, yt);
    x.lineTo(g.bx + Math.cos(a) * g.brothR, yb);
    x.strokeStyle = (i % 2) ? 'rgba(255,196,132,0.045)' : 'rgba(0,0,0,0.10)';
    x.stroke();
  }
  x.restore();

  x.restore();
}

function paintBrothBase(x, g) {
  x.save();
  x.translate(g.bx, g.by);
  x.scale(1, g.s);

  var rg = x.createRadialGradient(0, -g.brothR * 0.16, g.brothR * 0.03, 0, 0, g.brothR * 1.06);
  rg.addColorStop(0.00, '#f0b667');
  rg.addColorStop(0.13, '#d18c3c');
  rg.addColorStop(0.34, '#a15c1f');
  rg.addColorStop(0.60, '#6e380f');
  rg.addColorStop(0.84, '#451f07');
  rg.addColorStop(1.00, '#260f03');
  x.fillStyle = rg;
  x.beginPath();
  x.arc(0, 0, g.brothR, 0, TAU);
  x.fill();

  /* depth blotches so the liquid reads as opaque, not as flat paint */
  var rng = rngFrom(9911);
  x.save();
  x.beginPath();
  x.arc(0, 0, g.brothR, 0, TAU);
  x.clip();
  for (var i = 0; i < 16; i++) {
    var a = rng() * TAU, d = Math.sqrt(rng()) * g.brothR * 0.95;
    var bx = Math.cos(a) * d, by = Math.sin(a) * d;
    var br = g.brothR * (0.14 + rng() * 0.30);
    var warm = rng() < 0.5;
    var bg2 = x.createRadialGradient(bx, by, 0, bx, by, br);
    bg2.addColorStop(0, warm ? 'rgba(255,178,88,0.11)' : 'rgba(40,16,4,0.20)');
    bg2.addColorStop(1, warm ? 'rgba(255,178,88,0)' : 'rgba(40,16,4,0)');
    x.fillStyle = bg2;
    x.beginPath();
    x.arc(bx, by, br, 0, TAU);
    x.fill();
  }
  x.restore();

  /* meniscus: the liquid climbs the wall and darkens right at the edge */
  var mg = x.createRadialGradient(0, 0, g.brothR * 0.80, 0, 0, g.brothR);
  mg.addColorStop(0.00, 'rgba(20,7,0,0)');
  mg.addColorStop(0.72, 'rgba(20,7,0,0.30)');
  mg.addColorStop(1.00, 'rgba(12,4,0,0.72)');
  x.fillStyle = mg;
  x.beginPath();
  x.arc(0, 0, g.brothR, 0, TAU);
  x.fill();

  x.globalCompositeOperation = 'lighter';
  x.lineWidth = g.brothR * 0.012;
  x.beginPath();
  x.arc(0, 0, g.brothR * 0.985, Math.PI * 0.08, Math.PI * 0.92);
  x.strokeStyle = 'rgba(255,190,110,0.22)';
  x.stroke();
  x.globalCompositeOperation = 'source-over';

  x.restore();
}

function paintRim(x, g) {
  /* the lip: a bright thin ring, brightest at the back where it faces the light */
  var lg = x.createLinearGradient(0, g.cy - g.outRy, 0, g.cy + g.outRy);
  lg.addColorStop(0.00, '#6d5b4a');
  lg.addColorStop(0.34, '#2a2119');
  lg.addColorStop(0.62, '#171319');
  lg.addColorStop(1.00, '#3a2a1d');
  x.fillStyle = lg;
  x.fill(pRim, 'evenodd');

  x.save();
  x.clip(pRim, 'evenodd');
  x.globalCompositeOperation = 'lighter';
  var hg = x.createLinearGradient(g.cx - g.Ro, 0, g.cx + g.Ro, 0);
  hg.addColorStop(0.00, 'rgba(150,182,236,0.34)');
  hg.addColorStop(0.30, 'rgba(120,140,190,0.05)');
  hg.addColorStop(0.62, 'rgba(255,190,120,0.10)');
  hg.addColorStop(1.00, 'rgba(255,182,104,0.42)');
  x.fillStyle = hg;
  x.fillRect(g.cx - g.Ro - 2, g.cy - g.outRy - 2, g.Ro * 2 + 4, g.outRy * 2 + 4);
  x.globalCompositeOperation = 'source-over';
  x.restore();

  /* crisp inner and outer edges */
  x.lineWidth = Math.max(0.8, g.R * 0.006);
  x.beginPath();
  x.ellipse(g.cx, g.cy, g.Ro, g.outRy, 0, 0, TAU);
  x.strokeStyle = 'rgba(255,214,168,0.20)';
  x.stroke();

  x.beginPath();
  x.ellipse(g.cx, g.cy, g.R, g.rimRy, 0, Math.PI, TAU);
  x.strokeStyle = 'rgba(255,206,150,0.30)';
  x.stroke();

  x.beginPath();
  x.ellipse(g.cx, g.cy, g.R, g.rimRy, 0, 0, Math.PI);
  x.strokeStyle = 'rgba(0,0,0,0.45)';
  x.stroke();
}
