/* ============================================================
   5. the food  (baked into layer B)
   ============================================================ */

function contactShadow(x, g, u, v, rw, strength) {
  var b = P(g, u, v);
  var r = rw * g.brothR;
  x.save();
  x.translate(b.x, b.y);
  x.scale(1, g.s * 0.85);
  var sg = x.createRadialGradient(0, 0, 0, 0, 0, r);
  sg.addColorStop(0.00, 'rgba(22,8,0,' + strength + ')');
  sg.addColorStop(0.55, 'rgba(22,8,0,' + (strength * 0.45).toFixed(3) + ')');
  sg.addColorStop(1.00, 'rgba(22,8,0,0)');
  x.fillStyle = sg;
  x.beginPath();
  x.arc(0, 0, r, 0, TAU);
  x.fill();
  x.restore();
}

/* --- nori: a lacquered black sheet leaning on the far wall --- */
function drawNori(x, g, u, v, w, hh, lean) {
  var b = P(g, u, v);
  var W = w * g.brothR, H = hh * g.brothR;
  var lx = b.x - W / 2, rx = b.x + W / 2;
  var tlx = lx + lean * W, tly = b.y - H;
  var trx = rx + lean * W * 0.80, trY = b.y - H * 0.92;

  contactShadow(x, g, u, v + 0.02, w * 0.62, 0.55);

  var p = new Path2D();
  p.moveTo(lx, b.y);
  p.bezierCurveTo(lx - W * 0.07, b.y - H * 0.44, tlx - W * 0.05, tly + H * 0.30, tlx, tly);
  p.bezierCurveTo(tlx + W * 0.32, tly - H * 0.09, trx - W * 0.36, trY + H * 0.12, trx, trY);
  p.bezierCurveTo(trx + W * 0.06, trY + H * 0.36, rx + W * 0.06, b.y - H * 0.42, rx, b.y);
  p.closePath();

  var lg = x.createLinearGradient(0, tly, 0, b.y);
  lg.addColorStop(0.00, '#101a17');
  lg.addColorStop(0.30, '#0a110f');
  lg.addColorStop(0.72, '#0d1512');
  lg.addColorStop(1.00, '#251a0e');
  x.fillStyle = lg;
  x.fill(p);

  x.save();
  x.clip(p);
  x.globalCompositeOperation = 'lighter';

  /* satin sheen band across the sheet */
  var sg = x.createLinearGradient(lx, tly, rx, b.y);
  sg.addColorStop(0.00, 'rgba(90,150,170,0)');
  sg.addColorStop(0.30, 'rgba(96,158,180,0.13)');
  sg.addColorStop(0.46, 'rgba(150,210,225,0.20)');
  sg.addColorStop(0.62, 'rgba(96,158,180,0.09)');
  sg.addColorStop(1.00, 'rgba(70,120,140,0)');
  x.fillStyle = sg;
  x.fillRect(lx - W, tly - H, W * 3, H * 3);

  /* broth light bouncing onto the bottom of the sheet */
  var bg = x.createLinearGradient(0, b.y - H * 0.42, 0, b.y);
  bg.addColorStop(0, 'rgba(255,150,60,0)');
  bg.addColorStop(1, 'rgba(255,146,58,0.40)');
  x.fillStyle = bg;
  x.fillRect(lx - W, b.y - H * 0.5, W * 3, H * 0.6);
  x.globalCompositeOperation = 'source-over';

  /* pressed grain */
  x.lineWidth = Math.max(0.5, g.R * 0.0035);
  for (var i = 1; i < 13; i++) {
    var yy = b.y - (H * i / 13);
    x.beginPath();
    x.moveTo(lx + lean * W * (i / 13) - W * 0.04, yy + Math.sin(i * 1.7) * H * 0.012);
    x.lineTo(rx + lean * W * 0.8 * (i / 13) + W * 0.04, yy + Math.sin(i * 2.3 + 1) * H * 0.012);
    x.strokeStyle = (i % 3 === 0) ? 'rgba(140,190,200,0.045)' : 'rgba(0,0,0,0.16)';
    x.stroke();
  }
  x.restore();

  /* crisp lit top edge */
  x.lineWidth = Math.max(0.9, g.R * 0.006);
  x.beginPath();
  x.moveTo(tlx, tly);
  x.bezierCurveTo(tlx + W * 0.32, tly - H * 0.09, trx - W * 0.36, trY + H * 0.12, trx, trY);
  x.strokeStyle = 'rgba(178,220,228,0.34)';
  x.stroke();

  noriBox = { x0: Math.min(lx, tlx) - W * 0.08, x1: Math.max(rx, trx) + W * 0.08, y0: tly - H * 0.1, y1: b.y };
}

/* --- shiitake: domed cap with the traditional scored cross --- */
function drawShiitake(x, g, u, v, rad, rot) {
  var b = P(g, u, v);
  var rr = rad * g.brothR;
  var ry = rr * 0.58;
  var lift = rr * 0.30;
  var cxx = b.x, cyy = b.y - lift;

  contactShadow(x, g, u, v + rad * 0.16, rad * 1.5, 0.62);

  var p = new Path2D();
  p.ellipse(cxx, cyy, rr, ry, 0, 0, Math.PI, false);
  p.ellipse(cxx, cyy, rr, ry * 1.62, 0, Math.PI, TAU, false);
  p.closePath();

  var cg = x.createRadialGradient(cxx - rr * 0.34, cyy - ry * 0.95, rr * 0.05, cxx, cyy, rr * 1.35);
  cg.addColorStop(0.00, '#9c6534');
  cg.addColorStop(0.28, '#6d3f1c');
  cg.addColorStop(0.62, '#452310');
  cg.addColorStop(1.00, '#1d0d05');
  x.fillStyle = cg;
  x.fill(p);

  x.save();
  x.clip(p);

  /* scored cross, cut through to the pale flesh */
  x.save();
  x.translate(cxx, cyy - ry * 0.34);
  x.rotate(rot);
  x.lineCap = 'round';
  x.lineWidth = rr * 0.115;
  var cuts = [[-0.52, 0], [0.52, 0], [0, -0.34], [0, 0.34]];
  x.beginPath();
  x.moveTo(-rr * 0.60, 0); x.lineTo(rr * 0.60, 0);
  x.moveTo(-rr * 0.30, -ry * 0.62); x.lineTo(-rr * 0.30, ry * 0.62);
  x.moveTo(rr * 0.30, -ry * 0.62); x.lineTo(rr * 0.30, ry * 0.62);
  x.strokeStyle = 'rgba(226,198,152,0.60)';
  x.stroke();
  x.lineWidth = rr * 0.05;
  x.beginPath();
  x.moveTo(-rr * 0.60, rr * 0.05); x.lineTo(rr * 0.60, rr * 0.05);
  x.strokeStyle = 'rgba(30,14,4,0.5)';
  x.stroke();
  x.restore();
  void cuts;

  x.globalCompositeOperation = 'lighter';
  var sg = x.createRadialGradient(cxx - rr * 0.30, cyy - ry * 1.05, 0, cxx - rr * 0.30, cyy - ry * 1.05, rr * 0.95);
  sg.addColorStop(0.00, 'rgba(255,214,158,0.26)');
  sg.addColorStop(1.00, 'rgba(255,190,120,0)');
  x.fillStyle = sg;
  x.fillRect(cxx - rr * 1.2, cyy - ry * 2.2, rr * 2.4, ry * 4);

  /* warm bounce off the broth onto the cap underside */
  var ug = x.createLinearGradient(0, cyy, 0, cyy + ry);
  ug.addColorStop(0, 'rgba(255,130,40,0)');
  ug.addColorStop(1, 'rgba(255,132,42,0.36)');
  x.fillStyle = ug;
  x.fillRect(cxx - rr * 1.2, cyy, rr * 2.4, ry * 1.3);
  x.globalCompositeOperation = 'source-over';
  x.restore();

  x.lineWidth = Math.max(0.8, rr * 0.045);
  x.beginPath();
  x.ellipse(cxx, cyy, rr, ry * 1.62, 0, Math.PI * 1.12, TAU - 0.2);
  x.strokeStyle = 'rgba(255,196,132,0.24)';
  x.stroke();
}

/* --- menma: bamboo shoots, leaning in a small bundle --- */
function drawMenma(x, g, u, v, len, tilt, wdt) {
  var b = P(g, u, v);
  var L = len * g.brothR, W = wdt * g.brothR;
  var tipx = b.x + Math.sin(tilt) * L, tipy = b.y - Math.cos(tilt) * L;

  contactShadow(x, g, u, v + 0.02, wdt * 2.2, 0.45);

  var dx = tipx - b.x, dy = tipy - b.y;
  var l = Math.hypot(dx, dy) || 1;
  var px = -dy / l, py = dx / l;
  var p = new Path2D();
  p.moveTo(b.x + px * W, b.y + py * W);
  p.quadraticCurveTo(b.x + dx * 0.5 + px * W * 1.15, b.y + dy * 0.5 + py * W * 1.15, tipx + px * W * 0.58, tipy + py * W * 0.58);
  p.lineTo(tipx - px * W * 0.58, tipy - py * W * 0.58);
  p.quadraticCurveTo(b.x + dx * 0.5 - px * W * 0.85, b.y + dy * 0.5 - py * W * 0.85, b.x - px * W, b.y - py * W);
  p.closePath();

  var lg = x.createLinearGradient(b.x - px * W, b.y, b.x + px * W, b.y);
  lg.addColorStop(0.00, '#6d4c22');
  lg.addColorStop(0.34, '#c39a58');
  lg.addColorStop(0.58, '#e0bb7c');
  lg.addColorStop(1.00, '#8a6330');
  x.fillStyle = lg;
  x.fill(p);

  x.save();
  x.clip(p);
  x.lineWidth = Math.max(0.6, W * 0.16);
  for (var i = -1; i <= 1; i++) {
    x.beginPath();
    x.moveTo(b.x + px * W * i * 0.5, b.y + py * W * i * 0.5);
    x.lineTo(tipx + px * W * i * 0.3, tipy + py * W * i * 0.3);
    x.strokeStyle = 'rgba(80,52,20,0.34)';
    x.stroke();
  }
  x.globalCompositeOperation = 'lighter';
  var bg = x.createLinearGradient(0, b.y - L * 0.4, 0, b.y);
  bg.addColorStop(0, 'rgba(255,140,50,0)');
  bg.addColorStop(1, 'rgba(255,140,50,0.32)');
  x.fillStyle = bg;
  x.fillRect(b.x - L, b.y - L * 0.5, L * 2, L * 0.6);
  x.globalCompositeOperation = 'source-over';
  x.restore();

  x.lineWidth = Math.max(0.7, W * 0.22);
  x.beginPath();
  x.moveTo(tipx + px * W * 0.58, tipy + py * W * 0.58);
  x.lineTo(tipx - px * W * 0.58, tipy - py * W * 0.58);
  x.strokeStyle = 'rgba(255,228,176,0.42)';
  x.stroke();
}

/* --- tofu: a seared cube, built face by face --- */
function drawTofu(x, g, u, v, size, rot) {
  var b = P(g, u, v);
  var sz = size * g.brothR;
  var hgt = sz * 0.80;
  var i, j;

  contactShadow(x, g, u, v + size * 0.20, size * 1.5, 0.60);

  var base = [];
  for (i = 0; i < 4; i++) {
    var a = rot + i * TAU / 4 + Math.PI / 4;
    base.push({ x: b.x + Math.cos(a) * sz * 0.707, y: b.y + Math.sin(a) * sz * 0.707 * g.s });
  }
  var top = base.map(function (q) { return { x: q.x, y: q.y - hgt }; });

  var edges = [];
  for (i = 0; i < 4; i++) {
    j = (i + 1) % 4;
    edges.push({ i: i, j: j, mid: (base[i].y + base[j].y) / 2, mx: (base[i].x + base[j].x) / 2 });
  }
  edges.sort(function (p, q) { return p.mid - q.mid; });

  for (i = 0; i < 4; i++) {
    var e = edges[i];
    var na = Math.atan2(e.mid - b.y, e.mx - b.x);
    var lit = clamp(0.30 + 0.70 * Math.max(0, Math.cos(na - Math.PI * 0.40)), 0, 1);
    var fg = x.createLinearGradient(0, base[e.i].y - hgt, 0, base[e.i].y);
    fg.addColorStop(0.00, shade(214, 194, 152, lit * 0.92));
    fg.addColorStop(0.55, shade(178, 154, 112, lit * 0.80));
    fg.addColorStop(1.00, shade(150, 106, 54, lit * 0.86));
    x.fillStyle = fg;
    x.beginPath();
    x.moveTo(top[e.i].x, top[e.i].y);
    x.lineTo(top[e.j].x, top[e.j].y);
    x.lineTo(base[e.j].x, base[e.j].y);
    x.lineTo(base[e.i].x, base[e.i].y);
    x.closePath();
    x.fill();
    x.lineWidth = Math.max(0.8, sz * 0.045);
    x.strokeStyle = 'rgba(178,116,48,' + (0.30 * lit).toFixed(3) + ')';
    x.stroke();
  }

  x.beginPath();
  x.moveTo(top[0].x, top[0].y);
  for (i = 1; i < 4; i++) x.lineTo(top[i].x, top[i].y);
  x.closePath();
  var tg = x.createLinearGradient(b.x - sz * 0.7, b.y - hgt - sz * 0.4, b.x + sz * 0.7, b.y - hgt + sz * 0.4);
  tg.addColorStop(0.00, '#f2e6c8');
  tg.addColorStop(0.48, '#dfcda4');
  tg.addColorStop(1.00, '#b99f70');
  x.fillStyle = tg;
  x.fill();
  x.lineWidth = Math.max(0.9, sz * 0.05);
  x.strokeStyle = 'rgba(196,132,54,0.50)';
  x.stroke();

  /* a few charred flecks on the seared top */
  var rng = rngFrom(Math.round(u * 1000 + v * 733 + 17));
  for (i = 0; i < 7; i++) {
    var fa = rng() * TAU, fd = Math.sqrt(rng()) * sz * 0.44;
    x.beginPath();
    x.ellipse(b.x + Math.cos(fa) * fd, b.y - hgt + Math.sin(fa) * fd * g.s, sz * 0.05, sz * 0.03, fa, 0, TAU);
    x.fillStyle = 'rgba(140,84,30,' + (0.20 + rng() * 0.30).toFixed(2) + ')';
    x.fill();
  }
}

function shade(r, gg, bl, k) {
  return 'rgb(' + Math.round(r * k) + ',' + Math.round(gg * k) + ',' + Math.round(bl * k) + ')';
}

/* --- sweetcorn --- */
function drawKernel(x, g, u, v, sz, rot) {
  var b = P(g, u, v);
  var rw = sz * g.brothR, rh = rw * 0.86;
  var cyy = b.y - rh * 0.46;

  x.save();
  x.beginPath();
  x.ellipse(b.x, b.y + rh * 0.10, rw * 1.15, rw * 0.42, 0, 0, TAU);
  x.fillStyle = 'rgba(30,12,2,0.48)';
  x.fill();
  x.restore();

  x.beginPath();
  x.ellipse(b.x, cyy, rw, rh * 0.66, rot * 0.2, 0, TAU);
  var kg = x.createLinearGradient(b.x, cyy - rh * 0.7, b.x, cyy + rh * 0.7);
  kg.addColorStop(0.00, '#ffe9a2');
  kg.addColorStop(0.36, '#f6bd44');
  kg.addColorStop(0.78, '#c9801d');
  kg.addColorStop(1.00, '#8d5411');
  x.fillStyle = kg;
  x.fill();

  x.save();
  x.globalCompositeOperation = 'lighter';
  x.beginPath();
  x.ellipse(b.x - rw * 0.20, cyy - rh * 0.24, rw * 0.36, rh * 0.19, -0.42, 0, TAU);
  x.fillStyle = 'rgba(255,248,220,0.52)';
  x.fill();
  x.restore();
}

function drawCorn(x, g, u, v, n, spread, seed) {
  var rng = rngFrom(seed);
  var items = [], i;
  for (i = 0; i < n; i++) {
    var a = rng() * TAU, r = Math.sqrt(rng()) * spread;
    items.push({ u: u + Math.cos(a) * r, v: v + Math.sin(a) * r * 0.9, s: 0.030 + rng() * 0.014, rot: rng() * TAU });
  }
  items.sort(function (p, q) { return p.v - q.v; });
  for (i = 0; i < items.length; i++) drawKernel(x, g, items[i].u, items[i].v, items[i].s, items[i].rot);
}

/* --- bok choy: pale stems under a ruffled blade --- */
function leafPath(bx, by, tipx, tipy, width, ruffle, phase) {
  var p = new Path2D();
  var dx = tipx - bx, dy = tipy - by;
  var L = Math.hypot(dx, dy) || 1;
  var ux = dx / L, uy = dy / L;
  var px = -uy, py = ux;
  var N = 24, i, t, w;
  p.moveTo(bx, by);
  for (i = 1; i <= N; i++) {
    t = i / N;
    w = width * Math.pow(Math.sin(Math.PI * t), 0.60) * (1 + ruffle * Math.sin(t * 11 + phase));
    p.lineTo(bx + ux * L * t + px * w, by + uy * L * t + py * w);
  }
  for (i = N; i >= 0; i--) {
    t = i / N;
    w = width * Math.pow(Math.sin(Math.PI * t), 0.60) * (1 + ruffle * Math.sin(t * 9.5 - phase));
    p.lineTo(bx + ux * L * t - px * w, by + uy * L * t - py * w);
  }
  p.closePath();
  return p;
}

function drawBokChoy(x, g, u, v, sz, lean, seed) {
  var b = P(g, u, v);
  var H = sz * g.brothR;
  var rng = rngFrom(seed);
  var i;

  contactShadow(x, g, u, v + 0.02, sz * 0.9, 0.55);

  /* stems */
  for (i = 0; i < 4; i++) {
    var off = (i - 1.5) * H * 0.11;
    var tx = b.x + off * 1.3 + lean * H * 0.42;
    var ty = b.y - H * (0.40 + rng() * 0.14);
    var wdt = H * 0.075;
    var p = new Path2D();
    p.moveTo(b.x + off - wdt, b.y);
    p.quadraticCurveTo(b.x + off - wdt * 1.1, b.y - H * 0.24, tx - wdt * 0.42, ty);
    p.lineTo(tx + wdt * 0.42, ty);
    p.quadraticCurveTo(b.x + off + wdt * 1.1, b.y - H * 0.24, b.x + off + wdt, b.y);
    p.closePath();
    var sg = x.createLinearGradient(b.x + off - wdt, 0, b.x + off + wdt, 0);
    sg.addColorStop(0.00, '#7b8f5c');
    sg.addColorStop(0.42, '#dfe9c4');
    sg.addColorStop(0.72, '#b7c894');
    sg.addColorStop(1.00, '#67784a');
    x.fillStyle = sg;
    x.fill(p);
  }

  /* blade */
  var bx0 = b.x + lean * H * 0.30, by0 = b.y - H * 0.30;
  var tipx = b.x + lean * H * 1.05, tipy = b.y - H * 1.02;
  var lp = leafPath(bx0, by0, tipx, tipy, H * 0.34, 0.14, rng() * TAU);
  var lg = x.createLinearGradient(bx0, by0, tipx, tipy);
  lg.addColorStop(0.00, '#4c6b2e');
  lg.addColorStop(0.40, '#2f5626');
  lg.addColorStop(1.00, '#16371c');
  x.fillStyle = lg;
  x.fill(lp);

  x.save();
  x.clip(lp);
  x.globalCompositeOperation = 'lighter';
  var hg = x.createLinearGradient(bx0 - H * 0.3, by0, tipx + H * 0.3, tipy);
  hg.addColorStop(0.00, 'rgba(255,150,60,0.30)');
  hg.addColorStop(0.42, 'rgba(150,200,90,0.10)');
  hg.addColorStop(1.00, 'rgba(120,180,110,0.05)');
  x.fillStyle = hg;
  x.fillRect(b.x - H * 2, b.y - H * 2, H * 4, H * 4);
  x.globalCompositeOperation = 'source-over';
  x.lineWidth = Math.max(0.6, H * 0.012);
  x.strokeStyle = 'rgba(190,222,150,0.30)';
  x.beginPath();
  x.moveTo(bx0, by0);
  x.lineTo(tipx, tipy);
  x.stroke();
  for (i = 1; i <= 4; i++) {
    var t = i / 5;
    var vx = lerp(bx0, tipx, t), vy = lerp(by0, tipy, t);
    x.beginPath();
    x.moveTo(vx, vy);
    x.lineTo(vx - H * 0.20, vy - H * 0.06);
    x.moveTo(vx, vy);
    x.lineTo(vx + H * 0.20, vy - H * 0.06);
    x.strokeStyle = 'rgba(180,214,140,0.16)';
    x.stroke();
  }
  x.restore();
}

/* --- the noodles --- */
function buildNoodles(seed) {
  var rng = rngFrom(seed);
  var strands = [];
  var N = 34, i, k;
  for (i = 0; i < N; i++) {
    var layer = Math.pow(rng(), 0.70);
    var th = rng() * TAU;
    var d = (rng() * 2 - 1) * MOUND.r * 0.94;
    var half = Math.sqrt(Math.max(0.015, MOUND.r * MOUND.r - d * d)) * (0.82 + rng() * 0.46);
    var amp = MOUND.r * (0.085 + rng() * 0.095);
    var freq = (2.4 + rng() * 3.0) / MOUND.r;
    var ph = rng() * TAU;
    var ct = Math.cos(th), st = Math.sin(th);
    var pts = [];
    var STEPS = 26;
    for (k = 0; k <= STEPS; k++) {
      var t = (k / STEPS * 2 - 1) * half;
      var taper = 0.35 + 0.65 * Math.sin(Math.PI * (k / STEPS));
      var w = Math.sin(t * freq + ph) * amp * taper;
      var uu = MOUND.u + ct * t - st * (d + w);
      var vv = MOUND.v + st * t + ct * (d + w);
      var dome = surfaceHeight(uu, vv) / MOUND.h;
      var hgt = MOUND.h * dome * (0.26 + 0.76 * layer);
      hgt += Math.sin(t * freq * 1.7 + ph * 1.3) * MOUND.h * 0.032 * layer;
      pts.push({ u: uu, v: vv, h: Math.max(0, hgt) });
    }
    var mv = 0, mh = 0;
    for (k = 0; k < pts.length; k++) { mv += pts[k].v; mh += pts[k].h; }
    mv /= pts.length; mh /= pts.length;
    strands.push({ pts: pts, layer: layer, order: mv * 0.5 + (mh / MOUND.h) * 0.8, wk: 0.86 + rng() * 0.30 });
  }

  /* a couple of strands spilling off the front of the pile */
  for (i = 0; i < 4; i++) {
    var a0 = Math.PI * (0.20 + rng() * 0.60);
    var pts2 = [];
    var S2 = 20;
    for (k = 0; k <= S2; k++) {
      var tt = k / S2;
      var rr = MOUND.r * (0.20 + tt * 1.02);
      var ang = a0 + tt * (rng() > 0.5 ? 0.7 : -0.7);
      var uu2 = MOUND.u + Math.cos(ang) * rr + Math.sin(tt * 9 + i) * MOUND.r * 0.07;
      var vv2 = MOUND.v + Math.sin(ang) * rr * 0.9;
      var hh2 = MOUND.h * (0.85 * Math.pow(1 - tt, 1.7));
      pts2.push({ u: uu2, v: vv2, h: hh2 });
    }
    strands.push({ pts: pts2, layer: 1, order: 1.9 + i * 0.01, wk: 0.82 });
  }

  strands.sort(function (p, q) { return p.order - q.order; });
  return strands;
}

function strandPath(g, pts) {
  var p = new Path2D(), i;
  var sp = [];
  for (i = 0; i < pts.length; i++) {
    sp.push({
      x: g.bx + pts[i].u * g.brothR,
      y: g.by + pts[i].v * g.brothR * g.s - pts[i].h * g.brothR
    });
  }
  p.moveTo(sp[0].x, sp[0].y);
  for (i = 1; i < sp.length - 1; i++) {
    p.quadraticCurveTo(sp[i].x, sp[i].y, (sp[i].x + sp[i + 1].x) / 2, (sp[i].y + sp[i + 1].y) / 2);
  }
  p.lineTo(sp[sp.length - 1].x, sp[sp.length - 1].y);
  return p;
}

function drawNoodles(x, g, strands) {
  var topY = g.by + (MOUND.v - MOUND.r) * g.brothR * g.s - MOUND.h * g.brothR;
  var botY = g.by + (MOUND.v + MOUND.r * 1.4) * g.brothR * g.s;
  var w0 = g.brothR * 0.029;

  /* the pile darkens the broth it sits in */
  contactShadow(x, g, MOUND.u, MOUND.v + 0.04, MOUND.r * 1.35, 0.62);

  var body = x.createLinearGradient(0, topY, 0, botY);
  body.addColorStop(0.00, '#f8e2ad');
  body.addColorStop(0.26, '#e4c176');
  body.addColorStop(0.56, '#bd8f47');
  body.addColorStop(0.82, '#8a6228');
