/* ============================================================
   8. simulation
   ============================================================ */

function updateSteam(dt) {
  var g = G;
  var ns = 2.6 / g.R;
  var Rm = g.R * 0.66, Rm2 = Rm * Rm;
  var pvx = clamp(ptr.vx, -4000, 4000), pvy = clamp(ptr.vy, -4000, 4000);
  var drag = Math.exp(-1.05 * dt);

  for (var i = 0; i < steam.list.length; i++) {
    var p = steam.list[i];
    p.life += dt;
    if (p.life > p.maxLife || p.y < -g.R * 0.6) { respawnSteam(p, false); continue; }
    var t01 = p.life / p.maxLife;

    curl(p.x * ns, p.y * ns, T * 0.30, CURL);
    var turb = g.R * (0.30 + 1.05 * t01);
    p.vx += CURL.x * turb * dt;
    p.vy += CURL.y * turb * 0.62 * dt;

    /* buoyancy, fading as the plume cools */
    p.vy -= g.R * 0.34 * (1 - t01 * 0.72) * dt;
    p.vx += Math.sin(T * 0.23 + p.seed * 0.017) * g.R * 0.05 * dt;

    var dx = p.x - ptr.x, dy = p.y - ptr.y;
    var d2 = dx * dx + dy * dy;
    if (d2 < Rm2) {
      var d = Math.sqrt(d2) + 1e-3;
      var f = 1 - d / Rm;
      f = f * f;
      p.vx += (dx / d) * f * g.R * 2.2 * dt;
      p.vy += (dy / d) * f * g.R * 2.2 * dt;
      p.vx += pvx * f * 2.6 * dt;
      p.vy += pvy * f * 2.6 * dt;
    }

    p.vx *= drag;
    p.vy *= drag;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.rot += p.spin * dt;
  }
}

function renderSteam() {
  var g = G;
  var sc = steam.ctx, scv = steam.cv;
  sc.setTransform(1, 0, 0, 1, 0, 0);
  sc.clearRect(0, 0, scv.width, scv.height);
  sc.setTransform(steam.k, 0, 0, steam.k, 0, 0);
  sc.globalCompositeOperation = 'lighter';

  for (var i = 0; i < steam.list.length; i++) {
    var p = steam.list[i];
    var t01 = p.life / p.maxLife;
    var a = p.alpha * smooth(0, 0.20, t01) * (1 - smooth(0.48, 1, t01));
    if (a <= 0.0025) continue;
    var r = p.r0 * (1 + p.grow * t01);
    if (p.y + r < 0 || p.x + r < 0 || p.x - r > S.w) continue;

    var sp = Math.sqrt(p.vx * p.vx + p.vy * p.vy);
    var st = 1 + clamp(sp / (g.R * 0.60), 0, 1) * 0.9;
    sc.save();
    sc.translate(p.x, p.y);
    sc.rotate(Math.atan2(p.vy, p.vx) + p.rot * 0.06);
    sc.scale(st, 1 / Math.sqrt(st));
    sc.globalAlpha = a;
    sc.drawImage(steam.sprites[p.spr], -r, -r, r * 2, r * 2);
    sc.restore();
  }

  /* tint the accumulated density by height: amber at the bowl, cool as it dissipates */
  sc.setTransform(1, 0, 0, 1, 0, 0);
  sc.globalAlpha = 1;
  sc.globalCompositeOperation = 'source-in';
  var mouth = (g.cy - g.rimRy) * steam.k;
  var tg = sc.createLinearGradient(0, 0, 0, Math.max(mouth + 1, scv.height * 0.2));
  tg.addColorStop(0.00, 'rgba(126,148,186,0)');
  tg.addColorStop(0.16, 'rgba(146,164,198,0.42)');
  tg.addColorStop(0.44, 'rgba(196,196,198,0.86)');
  tg.addColorStop(0.72, 'rgba(244,214,180,1)');
  tg.addColorStop(1.00, 'rgba(255,182,104,1)');
  sc.fillStyle = tg;
  sc.fillRect(0, 0, scv.width, scv.height);
  sc.globalCompositeOperation = 'source-over';
}

function updateSurface(dt) {
  var i, o, a, d;
  for (i = 0; i < oil.length; i++) {
    o = oil[i];
    curl(o.u * 2.4 + 11, o.v * 2.4, T * 0.11, CURL);
    o.u += (CURL.x * 0.020 - o.v * 0.030) * o.sp * dt;
    o.v += (CURL.y * 0.020 + o.u * 0.030) * o.sp * dt;
    d = Math.sqrt(o.u * o.u + o.v * o.v);
    if (d > 0.93) { a = Math.random() * TAU; d = Math.sqrt(Math.random()) * 0.5; o.u = Math.cos(a) * d; o.v = Math.sin(a) * d; }
  }
  for (i = 0; i < flotsam.length; i++) {
    o = flotsam[i];
    curl(o.u * 2.1 - 5, o.v * 2.1 + 3, T * 0.09, CURL);
    o.u += (CURL.x * 0.016 - o.v * 0.026) * dt;
    o.v += (CURL.y * 0.016 + o.u * 0.026) * dt;
    o.rot += o.spin * dt;
    d = Math.sqrt(o.u * o.u + o.v * o.v);
    if (d > 0.90) { a = Math.random() * TAU; d = Math.sqrt(Math.random()) * 0.55; o.u = Math.cos(a) * d; o.v = Math.sin(a) * d; }
  }
  for (i = 0; i < shimmer.length; i++) {
    o = shimmer[i];
    curl(o.u * 1.5 + 21, o.v * 1.5, T * 0.07, CURL);
    o.u = clamp(o.u + CURL.x * 0.05 * dt, -0.8, 0.8);
    o.v = clamp(o.v + CURL.y * 0.05 * dt, -0.8, 0.8);
  }
  for (i = ripples.length - 1; i >= 0; i--) {
    ripples[i].t += dt;
    if (ripples[i].t > ripples[i].life) ripples.splice(i, 1);
  }
}

function updateDust(dt) {
  for (var i = 0; i < dust.length; i++) {
    var m = dust[i];
    m.y -= m.sp * dt;
    m.x += Math.sin(T * 0.4 + m.ph) * 5 * dt;
    m.ph += dt * 0.6;
    if (m.y < -8) { m.y = S.h + 8; m.x = Math.random() * S.w; }
  }
}

/* ============================================================
   9. frame
   ============================================================ */

function buildBackground() {
  var g = G, w = S.w, h = S.h;
  var far = Math.max(w, h);
  var b = {};

  b.base = ctx.createLinearGradient(0, 0, 0, h);
  b.base.addColorStop(0.00, '#04050a');
  b.base.addColorStop(0.42, '#07070d');
  b.base.addColorStop(0.72, '#0a0810');
  b.base.addColorStop(1.00, '#050509');

  b.warm = ctx.createRadialGradient(g.cx, g.cy - g.R * 0.18, g.R * 0.05, g.cx, g.cy - g.R * 0.18, far * 0.86);
  b.warm.addColorStop(0.00, 'rgba(214,116,44,0.30)');
  b.warm.addColorStop(0.16, 'rgba(178,88,32,0.16)');
  b.warm.addColorStop(0.42, 'rgba(126,56,20,0.06)');
  b.warm.addColorStop(1.00, 'rgba(90,36,12,0)');

  b.cool = ctx.createRadialGradient(w * 0.14, -h * 0.12, 0, w * 0.14, -h * 0.12, far * 0.85);
  b.cool.addColorStop(0.00, 'rgba(58,86,140,0.16)');
  b.cool.addColorStop(0.50, 'rgba(40,60,104,0.05)');
  b.cool.addColorStop(1.00, 'rgba(30,44,80,0)');

  b.vig = ctx.createRadialGradient(g.cx, g.cy - g.R * 0.05, g.R * 0.55, g.cx, g.cy, far * 0.80);
  b.vig.addColorStop(0.00, 'rgba(0,0,0,0)');
  b.vig.addColorStop(0.45, 'rgba(0,0,0,0.24)');
  b.vig.addColorStop(0.78, 'rgba(0,0,0,0.62)');
  b.vig.addColorStop(1.00, 'rgba(0,0,0,0.88)');

  S.bg = b;
}

function drawBackground(px, py) {
  var g = G, w = S.w, h = S.h;
  ctx.fillStyle = S.bg.base;
  ctx.fillRect(0, 0, w, h);

  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = S.bg.cool;
  ctx.fillRect(0, 0, w, h);

  var breathe = reduced ? 1 : (0.88 + 0.12 * Math.sin(T * 0.5) + 0.05 * Math.sin(T * 1.31));
  ctx.save();
  ctx.translate(-px * 2.2, -py * 2.2);
  ctx.globalAlpha = breathe;
  ctx.fillStyle = S.bg.warm;
  ctx.fillRect(-w, -h, w * 3, h * 3);
  ctx.globalAlpha = 1;
  ctx.restore();

  /* pool of light on the table */
  var py2 = g.cy + g.depth * 0.98;
  ctx.save();
  ctx.translate(g.cx + px * 0.4, py2 + py * 0.4);
  ctx.scale(1, 0.20);
  var pg = ctx.createRadialGradient(0, 0, 0, 0, 0, g.R * 2.5);
  pg.addColorStop(0.00, 'rgba(180,92,34,0.26)');
  pg.addColorStop(0.40, 'rgba(150,70,26,0.10)');
  pg.addColorStop(1.00, 'rgba(120,50,18,0)');
  ctx.fillStyle = pg;
  ctx.beginPath();
  ctx.arc(0, 0, g.R * 2.5, 0, TAU);
  ctx.fill();
  ctx.restore();
  ctx.globalCompositeOperation = 'source-over';

  /* contact shadow */
  ctx.save();
  ctx.translate(g.cx + px, g.cy + g.depth + g.footRy * 0.55 + py);
  ctx.scale(1, 0.24);
  var cg = ctx.createRadialGradient(0, 0, 0, 0, 0, g.R * 1.45);
  cg.addColorStop(0.00, 'rgba(0,0,0,0.92)');
  cg.addColorStop(0.34, 'rgba(0,0,0,0.60)');
  cg.addColorStop(1.00, 'rgba(0,0,0,0)');
  ctx.fillStyle = cg;
  ctx.beginPath();
  ctx.arc(0, 0, g.R * 1.45, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawDust(front, px, py) {
  ctx.globalCompositeOperation = 'lighter';
  for (var i = 0; i < dust.length; i++) {
    var m = dust[i];
    if (m.front !== front) continue;
    var tw = 0.55 + 0.45 * Math.sin(T * 1.4 + m.ph * 3);
    var a = m.a * tw * (front ? 1 : 0.6);
    var x = m.x + px * (front ? 3.2 : 1.1) * m.dep;
    var y = m.y + py * (front ? 2.4 : 0.8) * m.dep;
    var r = m.r * (front ? 1.25 : 0.9);
    var gr = ctx.createRadialGradient(x, y, 0, x, y, r * 4);
    gr.addColorStop(0, 'rgba(255,206,150,' + a.toFixed(3) + ')');
    gr.addColorStop(0.4, 'rgba(255,180,110,' + (a * 0.30).toFixed(3) + ')');
    gr.addColorStop(1, 'rgba(255,160,90,0)');
    ctx.fillStyle = gr;
    ctx.beginPath();
    ctx.arc(x, y, r * 4, 0, TAU);
    ctx.fill();
  }
  ctx.globalCompositeOperation = 'source-over';
}

function drawSurface() {
  var g = G, i;
  ctx.save();
  ctx.clip(pRimClip);
  ctx.save();
  ctx.clip(pBrothClip);

  /* drifting light on the liquid */
  ctx.save();
  ctx.translate(g.bx, g.by);
  ctx.scale(1, g.s);
  ctx.globalCompositeOperation = 'lighter';
  for (i = 0; i < shimmer.length; i++) {
    var sh = shimmer[i];
    var r = sh.r * g.brothR * (0.86 + 0.14 * Math.sin(T * 0.6 + sh.ph));
    var sx = sh.u * g.brothR, sy = sh.v * g.brothR;
    var sg = ctx.createRadialGradient(sx, sy, 0, sx, sy, r);
    var ai = 0.075 * (0.6 + 0.4 * Math.sin(T * 0.42 + sh.ph * 2));
    sg.addColorStop(0.00, 'rgba(255,196,116,' + ai.toFixed(3) + ')');
    sg.addColorStop(0.55, 'rgba(255,160,80,' + (ai * 0.35).toFixed(3) + ')');
    sg.addColorStop(1.00, 'rgba(255,140,60,0)');
    ctx.fillStyle = sg;
    ctx.beginPath();
    ctx.arc(sx, sy, r, 0, TAU);
    ctx.fill();
  }

  /* ripples */
  for (i = 0; i < ripples.length; i++) {
    var rp = ripples[i];
    var t = rp.t / rp.life;
    var rr = g.brothR * (0.03 + t * 0.62);
    var al = rp.str * (1 - t) * (1 - t) * 0.55;
    ctx.lineWidth = g.brothR * 0.016 * (1 - t * 0.6);
    ctx.strokeStyle = 'rgba(255,206,150,' + al.toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(rp.u * g.brothR, rp.v * g.brothR, rr, 0, TAU);
    ctx.stroke();
    ctx.lineWidth = g.brothR * 0.008 * (1 - t * 0.6);
    ctx.strokeStyle = 'rgba(255,236,200,' + (al * 0.7).toFixed(3) + ')';
    ctx.beginPath();
    ctx.arc(rp.u * g.brothR, rp.v * g.brothR, rr * 0.80, 0, TAU);
    ctx.stroke();
  }
  ctx.globalCompositeOperation = 'source-over';
  ctx.restore();

  /* oil lenses floating on top */
  for (i = 0; i < oil.length; i++) {
    var o = oil[i];
    var ox = g.bx + o.u * g.brothR;
    var oy = g.by + o.v * g.brothR * g.s;
    var orr = o.r * g.brothR * (1 + 0.05 * Math.sin(T * 1.1 + o.ph));
    var ory = orr * g.s * 1.05;
    ctx.beginPath();
    ctx.ellipse(ox, oy, orr, ory, 0, 0, TAU);
    var og = ctx.createRadialGradient(ox, oy - ory * 0.2, 0, ox, oy, orr);
    if (o.chili) {
      og.addColorStop(0.00, 'rgba(255,132,50,0.44)');
      og.addColorStop(0.62, 'rgba(224,78,22,0.34)');
      og.addColorStop(1.00, 'rgba(190,52,12,0.18)');
    } else {
      og.addColorStop(0.00, 'rgba(255,206,130,0.34)');
      og.addColorStop(0.62, 'rgba(240,160,66,0.24)');
      og.addColorStop(1.00, 'rgba(210,120,40,0.12)');
    }
    ctx.fillStyle = og;
    ctx.fill();

    ctx.globalCompositeOperation = 'lighter';
    ctx.lineWidth = Math.max(0.5, orr * 0.10);
    ctx.strokeStyle = 'rgba(255,224,168,0.34)';
    ctx.beginPath();
    ctx.ellipse(ox, oy, orr * 0.96, ory * 0.96, 0, 0, TAU);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(ox - orr * 0.30, oy - ory * 0.36, orr * 0.26, ory * 0.30, 0, 0, TAU);
    ctx.fillStyle = 'rgba(255,246,214,0.62)';
    ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  }

  ctx.restore();
  ctx.restore();
}

function drawFlotsam() {
  var g = G;
  ctx.save();
  ctx.clip(pBrothClip);
  for (var i = 0; i < flotsam.length; i++) {
    var f = flotsam[i];
    var fx = g.bx + f.u * g.brothR;
    var fy = g.by + f.v * g.brothR * g.s;
    /* anything behind the nori sheet is hidden by it */
    if (noriBox && f.v < -0.30 && fx > noriBox.x0 && fx < noriBox.x1 && fy > noriBox.y0 && fy < noriBox.y1) continue;
    var bob = Math.sin(T * 1.5 + f.rot * 3) * g.brothR * 0.004;
    if (f.kind < 0.60) {
      drawScallion(ctx, fx, fy + bob, f.sz * g.brothR, 0.60, f.pale, 0.96);
    } else if (f.kind < 0.86) {
      drawSesame(ctx, fx, fy + bob, f.sz * g.brothR * 0.40, 0.8, f.kind > 0.83, 0.9);
    } else {
      ctx.save();
      ctx.translate(fx, fy + bob);
      ctx.rotate(f.rot);
      ctx.scale(1, g.s);
      ctx.beginPath();
      ctx.ellipse(0, 0, f.sz * g.brothR * 1.5, f.sz * g.brothR * 0.42, 0, 0, TAU);
      ctx.fillStyle = 'rgba(112,168,74,0.85)';
      ctx.fill();
      ctx.restore();
    }
  }
  ctx.restore();
}

function drawBowlSpecular() {
  var g = G;
  var ax = clamp((ptr.x - g.cx) / g.R, -1.6, 1.6);
  var hx = g.cx + ax * g.R * 0.66;
  var hy = g.cy + g.depth * 0.34 - clamp((ptr.y - g.cy) / g.R, -1.5, 1.5) * g.R * 0.07;
  var rr = g.R * 0.62;
  ctx.save();
  ctx.clip(pBody);
  ctx.globalCompositeOperation = 'lighter';
  var sg = ctx.createRadialGradient(hx, hy, 0, hx, hy, rr);
  sg.addColorStop(0.00, 'rgba(255,214,168,0.14)');
  sg.addColorStop(0.42, 'rgba(255,186,124,0.045)');
  sg.addColorStop(1.00, 'rgba(255,170,110,0)');
  ctx.fillStyle = sg;
  ctx.fillRect(hx - rr, hy - rr, rr * 2, rr * 2);
  ctx.restore();
}

function drawMouthBloom() {
  var g = G;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.translate(g.cx, g.cy);
  ctx.scale(1, 0.62);
  var pulse = reduced ? 1 : (0.85 + 0.15 * Math.sin(T * 0.72 + 0.6));
  var bg = ctx.createRadialGradient(0, 0, g.R * 0.42, 0, 0, g.R * 1.75);
  bg.addColorStop(0.00, 'rgba(255,150,58,' + (0.20 * pulse).toFixed(3) + ')');
  bg.addColorStop(0.34, 'rgba(240,116,36,' + (0.10 * pulse).toFixed(3) + ')');
  bg.addColorStop(1.00, 'rgba(200,80,24,0)');
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.arc(0, 0, g.R * 1.75, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawPointerGlow() {
  var g = G;
  var sp = Math.min(1, Math.sqrt(ptr.vx * ptr.vx + ptr.vy * ptr.vy) / (g.R * 3));
  var inten = 0.040 + 0.045 * sp;
  var rr = g.R * 0.90;
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  var gr = ctx.createRadialGradient(ptr.x, ptr.y, 0, ptr.x, ptr.y, rr);
  gr.addColorStop(0.00, 'rgba(255,198,132,' + inten.toFixed(3) + ')');
  gr.addColorStop(0.40, 'rgba(255,162,90,' + (inten * 0.32).toFixed(3) + ')');
  gr.addColorStop(1.00, 'rgba(255,140,70,0)');
  ctx.fillStyle = gr;
  ctx.fillRect(ptr.x - rr, ptr.y - rr, rr * 2, rr * 2);
  ctx.restore();
}

function drawGrain() {
  if (!grainPat) return;
  var ox = reduced ? 0 : ((Math.random() * 180) | 0);
  var oy = reduced ? 0 : ((Math.random() * 180) | 0);
  ctx.save();
  ctx.globalCompositeOperation = 'overlay';
  ctx.globalAlpha = 0.42;
  ctx.translate(-ox, -oy);
  ctx.fillStyle = grainPat;
  ctx.fillRect(0, 0, S.w + 200, S.h + 200);
  ctx.restore();
}

function drawScene() {
  var g = G;
  var px = reduced ? 0 : clamp((ptr.x - S.cx) * 0.014, -g.R * 0.05, g.R * 0.05);
  var py = reduced ? 0 : clamp((ptr.y - S.cy) * 0.010, -g.R * 0.035, g.R * 0.035);

  ctx.setTransform(S.dpr, 0, 0, S.dpr, 0, 0);
  ctx.globalCompositeOperation = 'source-over';
  ctx.globalAlpha = 1;

  drawBackground(px, py);
  drawDust(false, px, py);

  ctx.save();
  ctx.translate(px, py);
  ctx.drawImage(LA.cv, BB.x, BB.y, LA.w, LA.h);
  drawSurface();
  ctx.drawImage(LB.cv, BB.x, BB.y, LB.w, LB.h);
  drawFlotsam();
  drawBowlSpecular();
  drawMouthBloom();
  ctx.restore();

  renderSteam();
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  ctx.drawImage(steam.cv, 0, 0, S.w, S.h);
  ctx.restore();

  drawPointerGlow();
  drawDust(true, px, py);

  ctx.fillStyle = S.bg.vig;
  ctx.fillRect(0, 0, S.w, S.h);
  drawGrain();
}
