/* ============================================================
   10. pointer, loop, lifecycle
   ============================================================ */

var rippleClock = 0;

function idleTarget(t) {
  var a = t * 0.16;
  return {
    x: S.cx + Math.cos(a) * S.w * 0.20 + Math.cos(a * 2.31 + 1.1) * S.w * 0.055,
    y: S.cy - S.R * 0.58 + Math.sin(a * 0.83) * S.h * 0.12 + Math.sin(a * 1.91) * S.h * 0.035
  };
}

function updatePointer(dt) {
  var now = T;
  var idle = (now - ptr.lastMove) > 2.4 || !ptr.everMoved;
  if (idle) {
    var it = idleTarget(now);
    var k = ptr.everMoved ? 0.45 : 1;
    ptr.tx = lerp(ptr.tx, it.x, clamp(k * dt * 1.4, 0, 1));
    ptr.ty = lerp(ptr.ty, it.y, clamp(k * dt * 1.4, 0, 1));
  }
  var ox = ptr.x, oy = ptr.y;
  var f = clamp(dt * 7.5, 0, 1);
  ptr.x = lerp(ptr.x, ptr.tx, f);
  ptr.y = lerp(ptr.y, ptr.ty, f);
  if (dt > 0) {
    ptr.vx = lerp(ptr.vx, (ptr.x - ox) / dt, 0.35);
    ptr.vy = lerp(ptr.vy, (ptr.y - oy) / dt, 0.35);
  }
}

function maybeRipple(dt) {
  var g = G;
  rippleClock -= dt;
  if (rippleClock <= 0) {
    rippleClock = 1.1 + Math.random() * 1.6;
    var a = Math.random() * TAU, d = Math.sqrt(Math.random()) * 0.72;
    addRipple(Math.cos(a) * d, Math.sin(a) * d, 0.42 + Math.random() * 0.3);
  }
  /* the cursor sweeping over the liquid nudges it */
  var u = (ptr.x - g.bx) / g.brothR;
  var v = (ptr.y - g.by) / (g.brothR * g.s);
  var sp = Math.sqrt(ptr.vx * ptr.vx + ptr.vy * ptr.vy);
  if (u * u + v * v < 0.82 && sp > g.R * 0.5 && Math.random() < dt * 7) {
    addRipple(u, v, clamp(sp / (g.R * 3), 0.25, 1));
  }
}

function step(dt) {
  T += dt;
  updatePointer(dt);
  maybeRipple(dt);
  updateSteam(dt);
  updateSurface(dt);
  updateDust(dt);
}

function frame(ts) {
  rafId = requestAnimationFrame(frame);
  if (!lastTs) lastTs = ts;
  var raw = ts - lastTs;
  lastTs = ts;
  var dt = clamp(raw / 1000, 0, 1 / 20);

  frameAvg = frameAvg * 0.94 + raw * 0.06;
  frameCount++;
  if (!downgraded && frameCount > 150 && frameAvg > 33) {
    downgraded = true;
    steam.ss = 0.34;
    initParticles();
  }

  step(dt);
  drawScene();
}

function start() {
  if (rafId || reduced) return;
  lastTs = 0;
  rafId = requestAnimationFrame(frame);
}

function stop() {
  if (rafId) { cancelAnimationFrame(rafId); rafId = 0; }
}

/* reduced motion: nothing animates on its own. the pointer still shifts the
   light softly, which is a direct response rather than autonomous movement. */
var staticPending = false;
function requestStatic() {
  if (!reduced || staticPending) return;
  staticPending = true;
  requestAnimationFrame(function () {
    staticPending = false;
    updatePointer(1);
    drawScene();
  });
}

function rebuild() {
  var el = cv;
  var w = Math.max(1, el.clientWidth || window.innerWidth || 1);
  var h = Math.max(1, el.clientHeight || window.innerHeight || 1);
  var dpr = clamp(window.devicePixelRatio || 1, 1, 2);

  S.w = w; S.h = h; S.dpr = dpr;
  cv.width = Math.round(w * dpr);
  cv.height = Math.round(h * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  S.R = Math.min(w * 0.40, h * 0.33, 520);
  S.cx = w * 0.5;
  S.cy = h * 0.615;

  G = buildGeom();
  BB = bowlBounds(G);
  buildPaths(G);
  buildBackground();
  if (!noodleStrands) noodleStrands = buildNoodles(3131);
  buildLayers();
  initParticles();

  ptr.tx = clamp(ptr.tx || S.cx, 0, w);
  ptr.ty = clamp(ptr.ty || S.cy - S.R * 0.5, 0, h);
  if (!ptr.everMoved) {
    var it = idleTarget(T);
    ptr.x = ptr.tx = it.x;
    ptr.y = ptr.ty = it.y;
  }

  /* let the plume establish itself before the first frame is seen */
  var warm = reduced ? 220 : 150;
  for (var i = 0; i < warm; i++) step(1 / 40);
}

var resizeTimer = 0;
function onResize() {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(function () {
    var el = cv;
    var w = el.clientWidth, h = el.clientHeight;
    if (w === S.w && h === S.h && clamp(window.devicePixelRatio || 1, 1, 2) === S.dpr) return;
    rebuild();
    if (reduced) requestStatic();
  }, 140);
}

function onPointer(e) {
  ptr.tx = e.clientX;
  ptr.ty = e.clientY;
  ptr.lastMove = T;
  ptr.everMoved = true;
  if (reduced) requestStatic();
}

function onDown(e) {
  onPointer(e);
  if (reduced) return;
  var g = G;
  var u = (e.clientX - g.bx) / g.brothR;
  var v = (e.clientY - g.by) / (g.brothR * g.s);
  if (u * u + v * v < 1.05) addRipple(clamp(u, -0.8, 0.8), clamp(v, -0.8, 0.8), 1);
  /* a puff of heat where you touched */
  for (var i = 0; i < steam.list.length; i++) {
    var p = steam.list[i];
    var dx = p.x - e.clientX, dy = p.y - e.clientY;
    var d = Math.sqrt(dx * dx + dy * dy) + 1e-3;
    if (d < g.R * 0.8) {
      var f = 1 - d / (g.R * 0.8);
      p.vx += (dx / d) * f * f * g.R * 1.6;
      p.vy += (dy / d) * f * f * g.R * 1.6 - g.R * 0.2 * f;
    }
  }
}

function applyMotionPref(mq) {
  reduced = !!mq.matches;
  if (reduced) {
    stop();
    rebuild();
    drawScene();
  } else {
    lastTs = 0;
    start();
  }
}

/* ---- boot ---- */
var mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : { matches: false, addEventListener: null };
reduced = !!mq.matches;

rebuild();
drawScene();

window.addEventListener('resize', onResize, { passive: true });
window.addEventListener('orientationchange', onResize, { passive: true });
if (window.ResizeObserver) { new ResizeObserver(onResize).observe(cv); }

window.addEventListener('pointermove', onPointer, { passive: true });
window.addEventListener('pointerdown', onDown, { passive: true });
window.addEventListener('pointerup', function () { ptr.lastMove = T; }, { passive: true });
window.addEventListener('pointercancel', function () { ptr.lastMove = T - 10; }, { passive: true });
window.addEventListener('blur', function () { ptr.lastMove = T - 10; });

document.addEventListener('visibilitychange', function () {
  if (document.hidden) stop();
  else { lastTs = 0; start(); }
});

if (mq.addEventListener) mq.addEventListener('change', applyMotionPref);
else if (mq.addListener) mq.addListener(applyMotionPref);

if (!reduced) start();

})();
</script>
</body>
</html>
