function rebuild() {
  var el = cv;
  var w = Math.max(1, el.clientWidth || window.innerWidth || 1);
  var h = Math.max(1, el.clientHeight || window.innerHeight || 1);
  var dpr = clamp(window.devicePixelRatio || 1, 1, 2);

  S.w = w; S.h = h; S.dpr = dpr;
  cv.width = Math.round(w * dpr);
  cv.height = Math.round(h * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  S.R = Math.min(w * 0.425, h * 0.395, 560);
  S.cx = w * 0.5;
  S.cy = h * 0.585;

  G = buildGeom();
  BB = bowlBounds(G);
  buildPaths(G);
  buildSprites();
  buildBackground();
  if (!noodleStrands) noodleStrands = buildNoodles(3131);
  buildLayers();
  initParticles();

  ptr.tx = clamp(ptr.tx || S.cx, 0, w);
  ptr.ty = clamp(ptr.ty || S.cy - S.R * 0.5, 0, h);
  if (!ptr.everMoved) {
    var it = idleTarget(T);
    ptr.x = ptr.tx = it.x;
    ptr.y = ptr.ty = it.y;
  }

  /* let the plume establish itself before the first frame is seen */
  var warm = reduced ? 220 : 150;
  for (var i = 0; i < warm; i++) step(1 / 40);
}

